 const DISCOVERIES={route:{name:'The tide-road marker',x:5,y:7,text:'A weathered post points back to Bramblebay. Travellers have tied strips of old ball wrappers to it. One reads: "Leave enough for the next person."',reward:25},forest:{name:'The root bridge',x:6,y:18,text:'Roots hold the bank together like linked hands. Fern has tucked a seed packet under the knot: "A forest is a family too. Return when your first egg hatches."',reward:30},orchard:{name:'Amber harvest baskets',x:5,y:15,text:'The harvest is sorted into baskets beside the road. A small card thanks the Tide companions that carried water here. Amber has left a few coins for the next lantern keeper.',reward:40},marsh:{name:'Reedglass listening post',x:14,y:18,text:'Hollow reeds hum when the wind crosses them. The old keepers used this quiet signal to guide travellers when the marsh path was hidden by rain.',reward:45},ruins:{name:'A broken family mosaic',x:4,y:12,text:'A parent and hatchling share the same pale stripe in the broken tiles. The archive was built to remember families, not champions. A sealed maintenance purse lies beneath the frame.',reward:50},ridge:{name:'Overlook field bench',x:5,y:16,text:'The whole valley lies below: the waterworks, forest roofs and the quarry lantern. Someone carved: "The best team is the one that brought you home." A trail fund envelope is tucked beneath the bench.',reward:60}};for(const [area,d]of Object.entries(DISCOVERIES))npcs[area].push({x:d.x,y:d.y,id:'discovery'});
 for(const [id,a]of Object.entries(ADVENTURE_ARCS)){npcs[a.area].push({x:a.x,y:a.y,id:'arc:'+id,art:a.art},{x:a.site.x,y:a.site.y,id:'site:'+id});const m=maps[a.area];for(const target of [a,a.site]){for(let x=10;x<=target.x;x++)m.grid[target.y][x]='path';for(let y=Math.min(a.y,a.site.y);y<=Math.max(a.y,a.site.y);y++)m.grid[y][a.x]='path';m.grid[target.y][target.x]='path';}}
