 function paintGroundLife(tiles){const style=['cave','mine','ruins'].includes(state.area)?'stone':state.area==='marsh'?'marsh':['village','town','harbor'].includes(state.area)?'town':'field';for(const tile of tiles){if(['water','path','house','fence'].includes(tile.t))continue;const key=style+':'+landHash(tile.x,tile.y,areaSeed(state.area))%83;let img=floorCache[key];if(!img){img=document.createElement('canvas');img.width=img.height=48;const c=img.getContext('2d');c.scale(3,3);paintGroundLifeTile(c,[{x:0,y:0,t:tile.t,seed:landHash(tile.x,tile.y,areaSeed(state.area))}]);floorCache[key]=img}ctx.drawImage(img,tile.x*16,tile.y*16,16,16)}}
