 function showSlots(){const b=openModal('Three journeys','LOCAL SAVE SLOTS');for(let n=1;n<=3;n++){let s;try{s=JSON.parse(localStorage.getItem('havenmoore-localfirst-prototype-slot-'+n))}catch{}const r=document.createElement('div');r.className='slot';r.innerHTML='<div>Slot '+n+(n===slot?' · Current':'')+'<small>'+(validSave(s)?SPECIES[s.party[0].id].name+' L'+s.party[0].level+' · '+s.party.length+' companions':'Empty')+'</small></div>';r.append(button(validSave(s)?'Load':'Begin',()=>{if(validSave(s)){save();if(load(n))toast('Loaded slot '+n+'.')}else{save();slot=n;state=fresh();update();showWelcome()}},'primary'));if(validSave(s))r.append(button('Reset',()=>confirmReset(n)));b.append(r)}b.insertAdjacentHTML('beforeend','<p class="note">Reset erases only the selected slot. Export first if you want a backup.</p>')}
