 const pad=document.querySelector('.dpad');let thumbId=null;const thumbAt=(x,y)=>{const r=pad.getBoundingClientRect();if(x<r.left||x>r.right||y<r.top||y>r.bottom)return null;const dx=x-r.left-r.width/2,dy=y-r.top-r.height/2;if(Math.abs(dx)<12&&Math.abs(dy)<12)return null;return Math.abs(dx)>Math.abs(dy)?dx<0?'left':'right':dy<0?'up':'down'};pad.addEventListener('pointerdown',e=>{if(thumbId!==null)return;e.preventDefault();thumbId=e.pointerId;pad.setPointerCapture(e.pointerId);held=thumbAt(e.clientX,e.clientY);if(held){move(held);lastStep=performance.now()}});pad.addEventListener('pointermove',e=>{if(e.pointerId===thumbId){e.preventDefault();held=thumbAt(e.clientX,e.clientY)}});for(const ev of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(ev,()=>{thumbId=null;held=null});
